// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address bankDeployer, address caller) public {
        vm.assume(bankDeployer != address(0));
        vm.assume(caller != address(0));

        vm.prank(bankDeployer);
        BankLike b = new BankLike();

        vm.deal(caller, 1 ether);

        vm.prank(address(b));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 bal = c.tokenBalance(address(b));

        if (ok) {
            assertTrue(bal == 20);
        } else {
            assertTrue(c.tokenBalance(address(b)) == 0);
        }
    }
}

contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address target) external {
        ModifierEntrancy(target).airDrop();
    }
}
